#include <stanli/function.hpp>
#include <chrono>
#include <cstdio>
#include <dlfcn.h>
#include <fstream>
#include <sstream>
#include <vector>
static int writer(void*, int, const double* values, size_t n, const int*, size_t,
                  const int64_t*, size_t) {
  return n == 32 && values[0] == 0.1 && values[31] == 15.6 ? 0 : 1;
}
int main(int argc, char** argv) {
  void* library = dlopen(argv[1], RTLD_NOW | RTLD_LOCAL);
  if (!library) { std::puts(dlerror()); return 1; }
  const auto create = reinterpret_cast<decltype(&stanli_function_new_from_mir)>(dlsym(library, "stanli_function_new_from_mir"));
  const auto call = reinterpret_cast<decltype(&stanli_function_call_values)>(dlsym(library, "stanli_function_call_values"));
  const auto destroy = reinterpret_cast<decltype(&stanli_function_free)>(dlsym(library, "stanli_function_free"));
  std::ifstream source("tests/fixtures/standalone_compiled.tmir.sexp"); std::stringstream text; text << source.rdbuf();
  char err[8192] = {}; auto* f = create(text.str().c_str(), "affine", err, sizeof(err));
  if (!f) { std::puts(err); return 1; }
  std::vector<double> x(32); for(int i=0;i<32;++i) x[i]=i;
  double a=.5, b=.1; int64_t n=32;
  stanli_function_argument args[]={{"x",0,x.data(),nullptr,32,&n,1},{"a",0,&a,nullptr,1,nullptr,0},{"b",0,&b,nullptr,1,nullptr,0}};
  auto measure = [&](double seconds) {
    using clock = std::chrono::steady_clock;
    const auto start=clock::now(); size_t count=0; double elapsed=0;
    do {
      for(int i=0;i<1000;++i) { if(call(f,args,3,writer,nullptr,err,sizeof(err))) {std::puts(err);std::exit(2);} }
      count+=1000; elapsed=std::chrono::duration<double>(clock::now()-start).count();
    } while(elapsed<seconds);
    return elapsed*1e6/count;
  };
  measure(.3); const double us=measure(1.0); destroy(f);
  std::printf("{\"warm_call_us\":%.9g}\n",us);
}

